 9→export async function getPlanId(shop: string): Promise<PlanId> {
10→  const sub = await db.subscription.findUnique({
11→    where: { shop },
12→    select: { planId: true, status: true },
13→  });
14→  if (!sub || sub.status !== "active") return "free";
15→  const validPlans = Object.keys(PLAN_LIMITS) as PlanId[];
16→  return validPlans.includes(sub.planId as PlanId)
17→    ? (sub.planId as PlanId)
18→    : "free";
19→}
