59→export async function ensureSubscription(shop: string) {
60→  return db.subscription.upsert({
61→    where: { shop },
62→    create: {
63→      shop,
64→      planId: "free",
65→      status: "active",
66→      quizLimit: 1,
67→      responseLimit: 100,
68→    },
69→    update: {},
70→  });
71→}
