 4→interface PlanGateProps {
 5→  requiredPlan: PlanId;
 6→  currentPlan: PlanId;
 7→  featureName: string;
 8→  children: React.ReactNode;
 9→}
10→
11→const PLAN_ORDER: PlanId[] = ["free", "starter", "pro", "enterprise"];
12→
13→export function PlanGate({
14→  requiredPlan,
15→  currentPlan,
16→  featureName,
17→  children,
18→}: PlanGateProps) {
19→  const hasAccess =
20→    PLAN_ORDER.indexOf(currentPlan) >= PLAN_ORDER.indexOf(requiredPlan);
21→
22→  if (hasAccess) return <>{children}</>;
23→
24→  const planName =
25→    requiredPlan.charAt(0).toUpperCase() + requiredPlan.slice(1);
26→
27→  return (
28→    <Card>
29→      <BlockStack gap="400">
30→        <BlockStack gap="200">
31→          <Badge tone="warning">{`${planName} plan required`}</Badge>
32→          <Text variant="headingMd" as="h3">
33→            {featureName}
34→          </Text>
35→          <Text as="p" tone="subdued">
36→            Upgrade to the {planName} plan to access{" "}
37→            {featureName.toLowerCase()}.
38→          </Text>
39→        </BlockStack>
40→        <Button url="/app/billing" variant="primary">
41→          Upgrade to {planName}
42→        </Button>
43→      </BlockStack>
44→    </Card>
45→  );
46→}
