 77→export async function updateQuiz(
 78→  id: string,
 79→  shop: string,
 80→  data: {
 81→    title?: string;
 82→    description?: string | null;
 83→    status?: string;
 84→    settings?: string;
 85→    styling?: string;
 86→  }
 87→) {
 88→  const quiz = await db.quiz.findFirst({ where: { id, shop } });
