119→// ─── Plan limit helper (server-side only) ─────────────────────────────────────
120→
121→async function checkPlanLimit(shop: string): Promise<string | null> {
122→  const count = await db.quiz.count({
123→    where: { shop, status: { not: "archived" } },
124→  });
125→  const sub = await db.subscription.findUnique({
126→    where: { shop },
127→    select: { planId: true },
128→  });
129→  const planId = (sub?.planId ?? "free") as PlanId;
130→  const limit = PLAN_LIMITS[planId]?.quizLimit ?? 1;
131→  if (count >= limit) {
132→    return `You've reached the ${limit}-quiz limit for your ${planId} plan. Upgrade to create more.`;
133→  }
134→  return null;
135→}
