152→// ─── Action ───────────────────────────────────────────────────────────────────
153→
154→export const action = async ({
155→  request,
156→}: ActionFunctionArgs): Promise<ActionResult | UNSAFE_DataWithResponseInit<ActionResult>> => {
157→  const { session } = await authenticate.admin(request);
158→  const formData = await request.formData();
159→  const intent = formData.get("intent") as string;
160→
161→  try {
162→    // ── Create from template ─────────────────────────────────────────────────
163→    if (intent === "create-from-template") {
164→      const templateId = formData.get("templateId") as string;
165→      if (!templateId) {
166→        return data<ActionResult>(
167→          { error: "Template ID is required" },
168→          { status: 400 },
169→        );
170→      }
171→      const limitError = await checkPlanLimit(session.shop);
172→      if (limitError) {
173→        return data<ActionResult>({ error: limitError }, { status: 403 });
174→      }
175→      const quizId = await createQuizFromTemplate(session.shop, templateId);
176→      return { success: true, quizId, message: "Quiz created from template!" };
177→    }
178→
179→    // ── Create blank ─────────────────────────────────────────────────────────
180→    if (intent === "create-blank") {
181→      const limitError = await checkPlanLimit(session.shop);
182→      if (limitError) {
183→        return data<ActionResult>({ error: limitError }, { status: 403 });
184→      }
185→      const quizId = await createBlankQuiz(session.shop);
186→      return { success: true, quizId, message: "Quiz created!" };
187→    }
188→
189→    // ── Archive ───────────────────────────────────────────────────────────────
190→    if (intent === "archive") {
191→      const id = formData.get("id") as string;
192→      const quiz = await db.quiz.findFirst({
193→        where: { id, shop: session.shop },
194→      });
195→      if (!quiz) {
196→        return data<ActionResult>(
197→          { error: "Quiz not found or access denied" },
198→          { status: 404 },
199→        );
200→      }
201→      await db.quiz.update({
202→        where: { id },
203→        data: { status: "archived" },
204→      });
205→      return { success: true, message: "Quiz archived" };
206→    }
207→
208→    // ── Delete ────────────────────────────────────────────────────────────────
209→    if (intent === "delete") {
210→      const id = formData.get("id") as string;
211→      await deleteQuiz(id, session.shop);
212→      return { success: true, message: "Quiz deleted" };
213→    }
214→
215→    return data<ActionResult>({ error: "Unknown intent" }, { status: 400 });
216→  } catch (error) {
217→    const message =
218→      error instanceof Error ? error.message : "Action failed";
219→    return data<ActionResult>({ error: message }, { status: 500 });
220→  }
221→};
