316→function AIGenerationOverlay({ onAnimationDone }: { onAnimationDone: () => void }) {
317→  const [currentStep, setCurrentStep] = useState(0);
318→  const [completedSteps, setCompletedSteps] = useState<number[]>([]);
319→
320→  useEffect(() => {
321→    const timers: ReturnType<typeof setTimeout>[] = [];
322→
323→    progressSteps.forEach((_, index) => {
324→      const advanceTimer = setTimeout(() => {
325→        setCurrentStep(index);
326→        if (index > 0) {
327→          setCompletedSteps((prev) =>
328→            prev.includes(index - 1) ? prev : [...prev, index - 1],
329→          );
330→        }
331→      }, index * 750);
332→      timers.push(advanceTimer);
333→    });
334→
335→    // Mark the last step complete
336→    const lastCompleteTimer = setTimeout(() => {
337→      setCompletedSteps((prev) =>
338→        prev.includes(progressSteps.length - 1)
339→          ? prev
340→          : [...prev, progressSteps.length - 1],
341→      );
342→    }, progressSteps.length * 750);
343→    timers.push(lastCompleteTimer);
344→
345→    // Signal animation is done with a small buffer
346→    const doneTimer = setTimeout(() => {
347→      onAnimationDone();
348→    }, progressSteps.length * 750 + 500);
349→    timers.push(doneTimer);
350→
351→    return () => timers.forEach(clearTimeout);
352→    // onAnimationDone is stable (wrapped in useCallback at the call site)
353→    // eslint-disable-next-line react-hooks/exhaustive-deps
354→  }, []);
355→
356→  return (
357→    <div
358→      style={{
359→        position: "fixed",
360→        inset: 0,
361→        zIndex: 9999,
362→        background: "rgba(255, 255, 255, 0.97)",
363→        display: "flex",
364→        alignItems: "center",
365→        justifyContent: "center",
366→      }}
367→    >
368→      <div style={{ textAlign: "center", maxWidth: 420 }}>
369→        {/* Spinner */}
370→        <div
371→          style={{
372→            width: 64,
373→            height: 64,
374→            margin: "0 auto 24px",
375→            border: "4px solid var(--p-color-border)",
376→            borderTopColor: "var(--p-color-border-emphasis)",
377→            borderRadius: "50%",
378→            animation: "quizsnap-spin 0.8s linear infinite",
379→          }}
380→        />
381→        <style>{`@keyframes quizsnap-spin { to { transform: rotate(360deg); } }`}</style>
382→
383→        <BlockStack gap="200">
384→          <Text as="p" variant="headingLg" fontWeight="bold">
385→            Building your quiz with AI...
386→          </Text>
387→          <Text as="p" variant="bodySm" tone="subdued">
388→            This usually takes a few seconds
389→          </Text>
390→        </BlockStack>
391→
392→        <div style={{ marginTop: 32, textAlign: "left" }}>
393→          <BlockStack gap="300">
394→            {progressSteps.map((step, index) => {
395→              const isCompleted = completedSteps.includes(index);
396→              const isCurrent = currentStep === index && !isCompleted;
397→              return (
398→                <InlineStack key={index} gap="300" blockAlign="center">
399→                  <div
400→                    style={{
401→                      width: 24,
402→                      height: 24,
403→                      borderRadius: "50%",
404→                      display: "flex",
405→                      alignItems: "center",
406→                      justifyContent: "center",
407→                      fontSize: 14,
408→                      flexShrink: 0,
409→                      background: isCompleted
410→                        ? "var(--p-color-bg-fill-success)"
411→                        : isCurrent
412→                          ? "var(--p-color-bg-fill-emphasis)"
413→                          : "var(--p-color-bg-surface-secondary)",
414→                      color:
415→                        isCompleted || isCurrent
416→                          ? "#fff"
417→                          : "var(--p-color-text-subdued)",
418→                    }}
419→                  >
420→                    {isCompleted ? "\u2713" : index + 1}
421→                  </div>
422→                  <Text
423→                    as="p"
424→                    variant="bodyMd"
425→                    tone={
426→                      isCompleted
427→                        ? "success"
428→                        : isCurrent
429→                          ? undefined
430→                          : "subdued"
431→                    }
432→                    fontWeight={isCurrent ? "semibold" : "regular"}
433→                  >
434→                    {step}
435→                  </Text>
436→                </InlineStack>
437→              );
438→            })}
439→          </BlockStack>
440→        </div>
441→      </div>
442→    </div>
443→  );
444→}
