448→export default function MyQuizzes() {
449→  const { quizzes, templates } = useLoaderData<typeof loader>();
450→  const navigate = useNavigate();
451→  const submit = useSubmit();
452→
453→  // Fetcher is used exclusively for quiz creation so the page doesn't navigate
454→  // away during submission (the action returns a quizId we then navigate to).
455→  const fetcher = useFetcher<ActionResult>();
456→
457→  const [createMenuOpen, setCreateMenuOpen] = useState(false);
458→  const [modalOpen, setModalOpen] = useState(false);
459→  const [templateMode, setTemplateMode] = useState<"ai" | "direct">("ai");
460→  const [showAIOverlay, setShowAIOverlay] = useState(false);
461→  const [animationDone, setAnimationDone] = useState(false);
462→
463→  const isCreating = fetcher.state !== "idle";
464→  const showEmptyState = quizzes.length === 0;
465→
466→  // ── Navigate after creation ────────────────────────────────────────────────
467→  useEffect(() => {
468→    if (!fetcher.data) return;
469→
470→    if ("error" in fetcher.data) {
471→      showToast(String(fetcher.data.error), { isError: true });
472→      setShowAIOverlay(false);
473→      setAnimationDone(false);
474→      return;
475→    }
476→
477→    if ("quizId" in fetcher.data && fetcher.data.quizId) {
478→      const { quizId, message } = fetcher.data;
479→
480→      if (!showAIOverlay) {
481→        // Blank quiz — navigate immediately
482→        showToast(message ?? "Quiz created!");
483→        navigate(`/app/quizzes/${quizId}`);
484→      } else if (animationDone) {
485→        // Template quiz — both animation and creation are complete
486→        showToast("AI built your quiz from your catalogue!");
487→        setShowAIOverlay(false);
488→        navigate(`/app/quizzes/${quizId}`);
489→      }
490→      // If quizId is ready but animation isn't done yet, the animationDone
491→      // branch of this effect will fire once animationDone flips to true.
492→    }
493→  }, [fetcher.data, animationDone, showAIOverlay, navigate]);
494→
495→  // ── Create menu actions ───────────────────────────────────────────────────
496→  const handleGenerateWithAI = useCallback(() => {
497→    setCreateMenuOpen(false);
498→    setTemplateMode("ai");
499→    setModalOpen(true);
500→  }, []);
501→
502→  const handleFromScratch = useCallback(() => {
503→    setCreateMenuOpen(false);
504→    fetcher.submit({ intent: "create-blank" }, { method: "POST" });
505→  }, [fetcher]);
506→
507→  const handleFromTemplate = useCallback(() => {
508→    setCreateMenuOpen(false);
509→    setTemplateMode("direct");
510→    setModalOpen(true);
511→  }, []);
512→
513→  const handleImportQuiz = useCallback(() => {
514→    setCreateMenuOpen(false);
515→    showToast("Import quiz coming soon!");
516→  }, []);
517→
518→  // ── Template selection (inside modal) ────────────────────────────────────
519→  const handleSelectTemplate = useCallback(
520→    (templateId: string) => {
521→      setModalOpen(false);
522→
523→      if (templateId === "blank") {
524→        fetcher.submit({ intent: "create-blank" }, { method: "POST" });
525→        return;
526→      }
527→
528→      if (templateMode === "ai") {
529→        // AI mode: show overlay while creating
530→        setShowAIOverlay(true);
531→        setAnimationDone(false);
532→      }
533→
534→      fetcher.submit(
535→        { intent: "create-from-template", templateId },
536→        { method: "POST" },
537→      );
538→    },
539→    [fetcher, templateMode],
540→  );
541→
542→  const handleAnimationDone = useCallback(() => {
543→    setAnimationDone(true);
544→  }, []);
545→
546→  // ── Row action handlers (use regular submit — archive/delete stay on page) ──
547→  const handleEditQuiz = useCallback(
548→    (id: string) => navigate(`/app/quizzes/${id}`),
549→    [navigate],
550→  );
551→
552→  const handlePreviewQuiz = useCallback(
553→    (id: string) => navigate(`/app/quizzes/${id}/preview`),
554→    [navigate],
555→  );
556→
557→  const handleArchiveQuiz = useCallback(
558→    (id: string) => {
559→      const formData = new FormData();
560→      formData.append("intent", "archive");
561→      formData.append("id", id);
562→      submit(formData, { method: "POST" });
563→      showToast("Quiz archived");
564→    },
565→    [submit],
566→  );
567→
568→  // ── IndexTable selection state ─────────────────────────────────────────────
569→  const resourceName = { singular: "quiz", plural: "quizzes" };
570→  const { selectedResources, allResourcesSelected, handleSelectionChange } =
571→    useIndexResourceState(quizzes);
572→
573→  // ── Row markup ─────────────────────────────────────────────────────────────
574→  const rowMarkup = quizzes.map(
575→    (
576→      quiz: {
577→        id: string;
578→        title: string;
579→        type: string;
580→        status: string;
581→        completions: number;
582→        updatedAt: Date | string;
583→        _count: { questions: number; responses: number };
584→      },
585→      index: number,
586→    ) => (
587→      <IndexTable.Row
588→        id={quiz.id}
589→        key={quiz.id}
590→        selected={selectedResources.includes(quiz.id)}
591→        position={index}
592→      >
593→        <IndexTable.Cell>
594→          <InlineStack gap="300" blockAlign="center">
595→            <Text as="span" variant="headingMd">
596→              {"📊"}
597→            </Text>
598→            <BlockStack gap="050">
599→              <Text as="span" variant="bodyMd" fontWeight="semibold">
600→                {quiz.title}
601→              </Text>
602→              <Text as="span" variant="bodySm" tone="subdued">
603→                {formatQuizType(quiz.type)}
604→              </Text>
605→            </BlockStack>
606→          </InlineStack>
607→        </IndexTable.Cell>
608→        <IndexTable.Cell>
609→          <Badge tone={statusToneMap[quiz.status]}>
610→            {formatStatus(quiz.status)}
611→          </Badge>
612→        </IndexTable.Cell>
613→        <IndexTable.Cell>
614→          <Text as="span" variant="bodyMd" alignment="end">
615→            {quiz._count.questions}
616→          </Text>
617→        </IndexTable.Cell>
618→        <IndexTable.Cell>
619→          <Text as="span" variant="bodyMd" alignment="end">
620→            {quiz.completions.toLocaleString()}
621→          </Text>
622→        </IndexTable.Cell>
623→        <IndexTable.Cell>
624→          <Text as="span" variant="bodyMd" alignment="end">
625→            {"—"}
626→          </Text>
627→        </IndexTable.Cell>
628→        <IndexTable.Cell>
629→          <Text as="span" variant="bodyMd" alignment="end">
630→            {"—"}
631→          </Text>
632→        </IndexTable.Cell>
633→        <IndexTable.Cell>
634→          <Text as="span" variant="bodySm" tone="subdued">
635→            {new Date(quiz.updatedAt).toLocaleDateString("en-US", {
636→              month: "short",
