641→        </IndexTable.Cell>
642→        <IndexTable.Cell>
643→          <ButtonGroup>
644→            <Button size="slim" onClick={() => handleEditQuiz(quiz.id)}>
645→              Edit
646→            </Button>
647→            <Button
648→              size="slim"
649→              variant="plain"
650→              onClick={() => handlePreviewQuiz(quiz.id)}
651→            >
652→              Preview
653→            </Button>
654→            <Button
655→              size="slim"
656→              variant="plain"
657→              tone="critical"
658→              onClick={() => handleArchiveQuiz(quiz.id)}
659→            >
660→              Archive
661→            </Button>
662→          </ButtonGroup>
663→        </IndexTable.Cell>
664→      </IndexTable.Row>
665→    ),
666→  );
667→
668→  // ── All templates including the blank option ───────────────────────────────
669→  const allTemplates: TemplateMeta[] = [...templates, BLANK_TEMPLATE];
670→
671→  // ── Create menu popover ──────────────────────────────────────────────────
672→  const createMenuActivator = (
673→    <Button
674→      variant="primary"
675→      onClick={() => setCreateMenuOpen((open) => !open)}
676→      disclosure="down"
677→      loading={isCreating && !showAIOverlay}
678→    >
679→      Create new quiz
680→    </Button>
681→  );
682→
683→  // ── Render ─────────────────────────────────────────────────────────────────
684→  return (
685→    <>
686→      {showAIOverlay && (
687→        <AIGenerationOverlay onAnimationDone={handleAnimationDone} />
688→      )}
689→
690→      <Page
691→        title="My Quizzes"
692→        primaryAction={
693→          <Popover
694→            active={createMenuOpen}
695→            activator={createMenuActivator}
696→            onClose={() => setCreateMenuOpen(false)}
697→            preferredAlignment="right"
698→          >
699→            <ActionList
700→              items={[
701→                {
702→                  content: "Generate with AI",
703→                  icon: WandIcon,
704→                  onAction: handleGenerateWithAI,
705→                },
706→                {
707→                  content: "From scratch",
708→                  icon: NoteIcon,
709→                  onAction: handleFromScratch,
710→                },
711→                {
712→                  content: "From template",
713→                  icon: ThemeTemplateIcon,
714→                  onAction: handleFromTemplate,
715→                },
716→                {
717→                  content: "Import quiz",
718→                  icon: ImportIcon,
719→                  onAction: handleImportQuiz,
720→                },
721→              ]}
722→            />
723→          </Popover>
724→        }
725→      >
726→        <BlockStack gap="600">
727→          {showEmptyState ? (
728→            <Card>
729→              <EmptyState
730→                heading="Create your first quiz"
731→                action={{
732→                  content: "Create quiz",
733→                  onAction: () => setCreateMenuOpen(true),
734→                }}
735→                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
736→              >
737→                <p>
738→                  Build product recommendation quizzes that help your customers
739→                  find the perfect product and boost your sales.
740→                </p>
741→              </EmptyState>
742→            </Card>
743→          ) : (
744→            <Layout>
745→              <Layout.Section>
746→                <Card padding="0">
747→                  <BlockStack>
748→                    <Box padding="400">
749→                      <InlineStack align="space-between" blockAlign="center">
750→                        <Text as="h2" variant="headingMd">
751→                          All Quizzes
752→                        </Text>
753→                        <Text as="p" variant="bodySm" tone="subdued">
