export interface UpdateABTestData {
  name?: string;
  variants?: ABTestVariant[];
  trafficSplit?: ABTestTrafficSplit;
}

// ─── JSON helpers ─────────────────────────────────────────────────────────────

function parseVariants(raw: string): ABTestVariant[] {
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as ABTestVariant[]) : [];
  } catch {
    return [];
  }
}

function parseTrafficSplit(raw: string): ABTestTrafficSplit {
  try {
    const parsed = JSON.parse(raw);
    return parsed !== null && typeof parsed === "object" && !Array.isArray(parsed)
      ? (parsed as ABTestTrafficSplit)
      : {};
  } catch {
    return {};
  }
}

// ─── Deterministic variant assignment ─────────────────────────────────────────

function simpleHash(str: string): number {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) + hash + str.charCodeAt(i);
    hash = hash & hash; // Convert to 32-bit int
  }
  return Math.abs(hash);
}

/**
 * Deterministically assigns a session to a variant using a hash of
 * sessionId + testId. The same session always gets the same variant.
 *
 * Returns the variantId that should be served, or null if the test
 * has no variants or traffic split configured.
 */
export function assignVariant(
  testId: string,
  sessionId: string,
  variants: ABTestVariant[],
  trafficSplit: ABTestTrafficSplit
): string | null {
  if (variants.length === 0) return null;

  // Build an ordered bucket list from trafficSplit percentages
  // e.g. [{variantId, upTo}] sorted so we can find the bucket
  const buckets: Array<{ variantId: string; upTo: number }> = [];
  let cumulative = 0;

  for (const variant of variants) {
    const pct = trafficSplit[variant.id] ?? 0;
    cumulative += pct;
    buckets.push({ variantId: variant.id, upTo: cumulative });
  }

  const hash = simpleHash(`${sessionId}-${testId}`);
  const bucket = hash % 100;

  for (const b of buckets) {
    if (bucket < b.upTo) return b.variantId;
  }

  // Fallback to last variant if rounding leaves a gap
  return variants[variants.length - 1]?.id ?? null;
}

// ─── CRUD operations ──────────────────────────────────────────────────────────

export async function getABTests(shop: string) {
  const tests = await db.aBTest.findMany({
    where: { shop },
    orderBy: { createdAt: "desc" },
    include: {
      quiz: { select: { id: true, title: true } },
    },
  });

  return tests.map((t) => ({
    ...t,
    variants: parseVariants(t.variants),
    trafficSplit: parseTrafficSplit(t.trafficSplit),
  }));
}

export async function getABTestById(id: string, shop: string) {
  const test = await db.aBTest.findFirst({
    where: { id, shop },
    include: {
      quiz: { select: { id: true, title: true } },
    },
  });
  if (!test) return null;

  return {
    ...test,
    variants: parseVariants(test.variants),
    trafficSplit: parseTrafficSplit(test.trafficSplit),
  };
}

export async function createABTest(shop: string, data: CreateABTestData) {
  // Verify the quiz belongs to this shop
  const quiz = await db.quiz.findFirst({
    where: { id: data.quizId, shop },
    select: { id: true, title: true },
  });
  if (!quiz) throw new Error("Quiz not found or access denied");

  // Default: two variants — Control (A) and Variant (B) — each 50%
  const controlVariantId = `ctrl-${Date.now()}`;
  const testVariantId = `var-${Date.now() + 1}`;

  const defaultVariants: ABTestVariant[] = [
    {
      id: controlVariantId,
      name: "Control (A)",
      quizId: data.quizId,
      description: "Original quiz",
    },
    {
      id: testVariantId,
      name: "Variant (B)",
      quizId: data.quizId,
      description: "Test variant",
    },
  ];

  const defaultSplit: ABTestTrafficSplit = {
    [controlVariantId]: 50,
    [testVariantId]: 50,
  };

  return db.aBTest.create({
    data: {
      shop,
      name: data.name,
      quizId: data.quizId,
      status: "draft",
      variants: JSON.stringify(defaultVariants),
      trafficSplit: JSON.stringify(defaultSplit),
    },
  });
}

export async function updateABTest(
  id: string,
  shop: string,
  data: UpdateABTestData
) {
  const test = await db.aBTest.findFirst({ where: { id, shop } });
  if (!test) throw new Error("A/B test not found or access denied");

  return db.aBTest.update({
    where: { id },
    data: {
      ...(data.name !== undefined ? { name: data.name } : {}),
      ...(data.variants !== undefined
        ? { variants: JSON.stringify(data.variants) }
        : {}),
      ...(data.trafficSplit !== undefined
        ? { trafficSplit: JSON.stringify(data.trafficSplit) }
        : {}),
      updatedAt: new Date(),
    },
  });
}

export async function startABTest(id: string, shop: string) {
  const test = await db.aBTest.findFirst({ where: { id, shop } });
  if (!test) throw new Error("A/B test not found or access denied");
  if (test.status === "running") throw new Error("Test is already running");
  if (test.status === "completed") throw new Error("Cannot restart a completed test");

  return db.aBTest.update({
    where: { id },
    data: { status: "running", startedAt: new Date(), updatedAt: new Date() },
  });
}

export async function pauseABTest(id: string, shop: string) {
  const test = await db.aBTest.findFirst({ where: { id, shop } });
  if (!test) throw new Error("A/B test not found or access denied");
  if (test.status !== "running") throw new Error("Only running tests can be paused");

  return db.aBTest.update({
    where: { id },
    data: { status: "paused", updatedAt: new Date() },
  });
}

export async function completeABTest(
  id: string,
  shop: string,
  winnerVariant: string
) {
  const test = await db.aBTest.findFirst({ where: { id, shop } });
  if (!test) throw new Error("A/B test not found or access denied");
  if (test.status === "completed") throw new Error("Test is already completed");

  return db.aBTest.update({
    where: { id },
    data: {
      status: "completed",
      winnerVariant,
      endedAt: new Date(),
      updatedAt: new Date(),
    },
  });
}

export async function deleteABTest(id: string, shop: string): Promise<void> {
  const test = await db.aBTest.findFirst({ where: { id, shop } });
  if (!test) throw new Error("A/B test not found or access denied");
  // Never delete — archive the losing variant per Law 15.
  // For A/B test records themselves, we allow deletion since they are not
  // ProductMapping records. The quiz variants remain intact (soft-delete
  // is on ProductMapping, hard-delete cascades from Quiz).
  await db.aBTest.delete({ where: { id } });
}

