import { data } from "react-router";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
  UNSAFE_DataWithResponseInit,
} from "react-router";
import { useLoaderData, useSubmit, useFetcher } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Badge,
  Button,
  Box,
  IndexTable,
  Modal,
  TextField,
  Select,
  EmptyState,
  SkeletonPage,
  SkeletonBodyText,
  ButtonGroup,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import {
  getABTests,
  createABTest,
  startABTest,
  pauseABTest,
  deleteABTest,
} from "../services/ab-test.server";
import { getPlanId } from "../services/billing.server";
