import { ConfirmModal } from "../components/shared/ConfirmModal";
import db from "../db.server";
import type { PlanId } from "../utils/constants";

// ─── Types ────────────────────────────────────────────────────────────────────

type ABTestStatus = "draft" | "running" | "completed" | "paused";

type BadgeTone =
  | "success"
  | "attention"
  | "info"
  | "warning"
  | "critical"
  | undefined;

type ActionSuccess = { success: true; message: string };
type ActionError = { error: string };
type ActionResult = ActionSuccess | ActionError;

type QuizOption = { label: string; value: string };

// ─── Status helpers ───────────────────────────────────────────────────────────

const statusToneMap: Record<ABTestStatus, BadgeTone> = {
  draft: "attention",
  running: "success",
  completed: "info",
  paused: "warning",
};

function formatStatus(status: string): string {
  return status.charAt(0).toUpperCase() + status.slice(1);
}

// ─── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  try {
    const [abTests, planId, quizRows] = await Promise.all([
      getABTests(session.shop),
      getPlanId(session.shop),
      db.quiz.findMany({
        where: { shop: session.shop, status: { not: "archived" } },
        select: { id: true, title: true },
        orderBy: { title: "asc" },
      }),
    ]);

    const quizOptions: QuizOption[] = quizRows.map((q) => ({
      label: q.title,
      value: q.id,
    }));

    return { abTests, planId: planId as PlanId, quizOptions };
  } catch {
    return {
      abTests: [],
      planId: "free" as PlanId,
      quizOptions: [] as QuizOption[],
    };
  }
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({
  request,
}: ActionFunctionArgs): Promise<
  ActionResult | UNSAFE_DataWithResponseInit<ActionResult>
> => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    // ── Create ────────────────────────────────────────────────────────────────
    if (intent === "create") {
      const name = (formData.get("name") as string | null)?.trim();
      const quizId = formData.get("quizId") as string | null;

      if (!name) {
        return data<ActionResult>(
          { error: "Test name is required" },
          { status: 400 }
        );
      }
      if (!quizId) {
        return data<ActionResult>(
          { error: "Please select a quiz" },
          { status: 400 }
        );
      }

      await createABTest(session.shop, { name, quizId });
      return { success: true, message: "A/B test created" };
    }

    // ── Start ─────────────────────────────────────────────────────────────────
    if (intent === "start") {
      const id = formData.get("id") as string;
      await startABTest(id, session.shop);
      return { success: true, message: "Test started" };
    }

    // ── Pause ─────────────────────────────────────────────────────────────────
    if (intent === "pause") {
      const id = formData.get("id") as string;
      await pauseABTest(id, session.shop);
      return { success: true, message: "Test paused" };
    }

    // ── Delete ────────────────────────────────────────────────────────────────
    if (intent === "delete") {
      const id = formData.get("id") as string;
      await deleteABTest(id, session.shop);
      return { success: true, message: "Test deleted" };
    }

    return data<ActionResult>({ error: "Unknown intent" }, { status: 400 });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Action failed";
    return data<ActionResult>({ error: message }, { status: 500 });
  }
};

// ─── HydrateFallback (skeleton) ───────────────────────────────────────────────

export function HydrateFallback() {
  return (
    <SkeletonPage title="A/B Tests" primaryAction>
      <BlockStack gap="600">
        <Card>
          <SkeletonBodyText lines={8} />
        </Card>
      </BlockStack>
    </SkeletonPage>
  );
}

// ─── Main page ────────────────────────────────────────────────────────────────

export default function ABTestsPage() {
  const { abTests, planId, quizOptions } = useLoaderData<typeof loader>();
  const submit = useSubmit();
  const fetcher = useFetcher<ActionResult>();

  // ── Modal state ──────────────────────────────────────────────────────────
  const [createModalOpen, setCreateModalOpen] = useState(false);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);

  // ── Form state ───────────────────────────────────────────────────────────
  const [testName, setTestName] = useState("");
  const [selectedQuizId, setSelectedQuizId] = useState(
    quizOptions[0]?.value ?? ""
  );
  const [nameError, setNameError] = useState<string | undefined>(undefined);
  const [quizError, setQuizError] = useState<string | undefined>(undefined);

  const isCreating = fetcher.state !== "idle";

  // ── Toast on fetcher result ───────────────────────────────────────────────
  useEffect(() => {
    if (!fetcher.data) return;
    if ("error" in fetcher.data) {
      showToast(String(fetcher.data.error), { isError: true });
    } else {
      showToast(fetcher.data.message);
      // Close create modal on success
      setCreateModalOpen(false);
      setTestName("");
      setSelectedQuizId(quizOptions[0]?.value ?? "");
    }
  }, [fetcher.data, quizOptions]);

  // ── Create modal handlers ─────────────────────────────────────────────────
  const handleOpenCreate = useCallback(() => {
    setTestName("");
    setSelectedQuizId(quizOptions[0]?.value ?? "");
    setNameError(undefined);
    setQuizError(undefined);
    setCreateModalOpen(true);
  }, [quizOptions]);

  const handleCloseCreate = useCallback(() => {
    setCreateModalOpen(false);
  }, []);

  const handleCreateSubmit = useCallback(() => {
    let hasError = false;
    if (!testName.trim()) {
      setNameError("Test name is required");
      hasError = true;
    } else {
      setNameError(undefined);
    }
    if (!selectedQuizId) {
      setQuizError("Please select a quiz");
      hasError = true;
    } else {
      setQuizError(undefined);
    }
    if (hasError) return;

    fetcher.submit(
      { intent: "create", name: testName.trim(), quizId: selectedQuizId },
      { method: "POST" }
    );
  }, [fetcher, testName, selectedQuizId]);

  // ── Start / Pause handlers ────────────────────────────────────────────────
  const handleStart = useCallback(
    (id: string) => {
      const formData = new FormData();
      formData.append("intent", "start");
      formData.append("id", id);
      submit(formData, { method: "POST" });
      showToast("Test started");
    },
    [submit]
  );

  const handlePause = useCallback(
    (id: string) => {
      const formData = new FormData();
      formData.append("intent", "pause");
      formData.append("id", id);
      submit(formData, { method: "POST" });
      showToast("Test paused");
    },
    [submit]
  );

  // ── Delete modal handlers ─────────────────────────────────────────────────
  const handleOpenDelete = useCallback((id: string) => {
    setPendingDeleteId(id);
    setDeleteModalOpen(true);
  }, []);

  const handleCloseDelete = useCallback(() => {
    setDeleteModalOpen(false);
    setPendingDeleteId(null);
  }, []);

  const handleConfirmDelete = useCallback(() => {
    if (!pendingDeleteId) return;
    const formData = new FormData();
    formData.append("intent", "delete");
    formData.append("id", pendingDeleteId);
    submit(formData, { method: "POST" });
    showToast("Test deleted");
    setDeleteModalOpen(false);
    setPendingDeleteId(null);
  }, [pendingDeleteId, submit]);

  // ── Row markup ────────────────────────────────────────────────────────────
  const rowMarkup = abTests.map(
    (
      test: {
        id: string;
        name: string;
        status: string;
        variants: Array<{ id: string; name: string; quizId: string; description: string }>;
        startedAt: Date | string | null;
        quiz: { id: string; title: string };
      },
      index: number
    ) => {
      const statusKey = test.status as ABTestStatus;
      return (
        <IndexTable.Row id={test.id} key={test.id} position={index}>
          <IndexTable.Cell>
            <Text as="span" variant="bodyMd" fontWeight="semibold">
              {test.name}
            </Text>
          </IndexTable.Cell>
          <IndexTable.Cell>
            <Text as="span" variant="bodySm" tone="subdued">
              {test.quiz.title}
            </Text>
          </IndexTable.Cell>
          <IndexTable.Cell>
            <Badge tone={statusToneMap[statusKey] ?? undefined}>
              {formatStatus(test.status)}
            </Badge>
          </IndexTable.Cell>
          <IndexTable.Cell>
            <Text as="span" variant="bodyMd">
              {test.variants.length}
            </Text>
          </IndexTable.Cell>
          <IndexTable.Cell>
            <Text as="span" variant="bodySm" tone="subdued">
              {test.startedAt
                ? new Date(test.startedAt).toLocaleDateString("en-US", {
                    month: "short",
                    day: "numeric",
                    year: "numeric",
                  })
                : "—"}
            </Text>
          </IndexTable.Cell>
          <IndexTable.Cell>
            <ButtonGroup>
              {test.status === "draft" && (
                <Button size="slim" onClick={() => handleStart(test.id)}>
                  Start
                </Button>
              )}
              {test.status === "running" && (
                <Button
                  size="slim"
                  variant="plain"
                  onClick={() => handlePause(test.id)}
                >
                  Pause
                </Button>
              )}
              {test.status === "paused" && (
                <Button size="slim" onClick={() => handleStart(test.id)}>
                  Resume
                </Button>
              )}
              <Button
                size="slim"
                variant="plain"
                tone="critical"
                onClick={() => handleOpenDelete(test.id)}
              >
                Delete
              </Button>
            </ButtonGroup>
          </IndexTable.Cell>
        </IndexTable.Row>
      );
    }
  );

  // ── Select options ────────────────────────────────────────────────────────
  const quizSelectOptions =
    quizOptions.length > 0
      ? quizOptions
      : [{ label: "No quizzes available", value: "" }];

  // ── Render ────────────────────────────────────────────────────────────────
  return (
    <>
      <Page
        title="A/B Tests"
        primaryAction={{
          content: "Create test",
          onAction: handleOpenCreate,
          disabled: planId !== "pro" && planId !== "enterprise",
        }}
      >
        <PlanGate
          requiredPlan="pro"
          currentPlan={planId}
          featureName="A/B Testing"
        >
          <BlockStack gap="600">
            {abTests.length === 0 ? (
              <Card>
                <EmptyState
                  heading="Run your first A/B test"
                  action={{
                    content: "Create test",
                    onAction: handleOpenCreate,
                  }}
                  image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
                >
                  <p>
                    Compare two quiz variants head-to-head to discover which
                    drives more completions and conversions.
                  </p>
                </EmptyState>
              </Card>
            ) : (
              <Layout>
                <Layout.Section>
                  <Card padding="0">
                    <BlockStack>
                      <Box padding="400">
                        <InlineStack align="space-between" blockAlign="center">
                          <Text as="h2" variant="headingMd">
                            All A/B Tests
                          </Text>
                          <Text as="p" variant="bodySm" tone="subdued">
                            {abTests.length}{" "}
                            {abTests.length === 1 ? "test" : "tests"}
                          </Text>
                        </InlineStack>
                      </Box>
                      <IndexTable
                        resourceName={{ singular: "test", plural: "tests" }}
                        itemCount={abTests.length}
                        headings={[
                          { title: "Name" },
                          { title: "Quiz" },
                          { title: "Status" },
                          { title: "Variants" },
                          { title: "Started" },
                          { title: "Actions" },
                        ]}
                        selectable={false}
                      >
                        {rowMarkup}
                      </IndexTable>
                    </BlockStack>
                  </Card>
                </Layout.Section>
              </Layout>
            )}
          </BlockStack>
        </PlanGate>
      </Page>

      {/* Create test modal */}
      <Modal
        open={createModalOpen}
        onClose={handleCloseCreate}
        title="Create A/B Test"
        primaryAction={{
          content: "Create test",
          onAction: handleCreateSubmit,
          loading: isCreating,
        }}
        secondaryActions={[{ content: "Cancel", onAction: handleCloseCreate }]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            <TextField
              label="Test name"
              value={testName}
              onChange={setTestName}
              autoComplete="off"
              placeholder="e.g. Skincare Quiz — Button CTA vs Text CTA"
              error={nameError}
            />
            <Select
              label="Quiz to test"
              options={quizSelectOptions}
              value={selectedQuizId}
              onChange={setSelectedQuizId}
              error={quizError}
              helpText="Both variants will use this quiz as their base."
            />
          </BlockStack>
        </Modal.Section>
      </Modal>

      {/* Confirm delete modal */}
      <ConfirmModal
        open={deleteModalOpen}
        onClose={handleCloseDelete}
        onConfirm={handleConfirmDelete}
        title="Delete A/B test?"
        message="This will permanently delete the test and its configuration. The quizzes themselves will not be affected."
        confirmLabel="Delete test"
        destructive
      />
    </>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};
